scripts.script:
def ensureProperty(propName) {
  def value = session.userProperties.getProperty(propName)
  if (value == null || value.trim().isEmpty()) {
    value = "*"
    session.userProperties.setProperty(propName, value)
    project.properties.setProperty(propName, value)
    System.setProperty(propName, value)
  } else if (project.properties.getProperty(propName) == null || project.properties.getProperty(propName).trim().isEmpty()) {
    project.properties.setProperty(propName, value)
  }
}
ensureProperty("git.branch")
ensureProperty("git.commit.id.abbrev")
